    if (((type_node == 0) || (type_node -> kind != LM_P0_NODE_FRAME)) || (lm_trans_text_is_array_receiver_head(type_node -> as -> frame -> head) == 0)) {
        return 0;
    }
    body = lm_trans_unwrap_single_anonymous_structure(type_node -> as -> frame -> body);
